func FetchAll(urls []string) []Result {
	var results []Result
	var wg sync.WaitGroup
	for _, u := range urls {
		wg.Add(1)
		go func() {
			defer wg.Done()
			results = append(results, Result{u})
		}()
	}
	wg.Wait()
	return results
}
